import java.util.*;
public class PaydayLendingApp {
    public static void main(String[] args) {
        // Initialize variables
        double interestRate = 0.5;
        double minimumLoanAmount = 1000;
        double maximumLoanAmount = 50000;
        double currentBalance = 0;
        double totalInterestPaid = 0;
        double totalInterestEarned = 0;

        // Prompt user for loan amount
        System.out.println("Welcome to the Payday Lending App!");
        System.out.println("Please enter the amount you would like to borrow:");
        Scanner scanner = new Scanner(System.in);
        double loanAmount = scanner.nextDouble();

        // Check if loan amount is within range
        if (loanAmount < minimumLoanAmount || loanAmount > maximumLoanAmount) {
            System.out.println("Loan amount must be between " + minimumLoanAmount + " and " + maximumLoanAmount);
            return;
        }

        // Calculate interest earned
        double interestEarned = loanAmount * interestRate;
        totalInterestEarned += interestEarned;

        // Calculate total interest paid
        double totalInterestPaid = loanAmount * interestRate;
        totalInterestPaid += totalInterestPaid;

        // Print results
        System.out.println("Total interest earned: " + totalInterestEarned);
        System.out.println("Total interest paid: " + totalInterestPaid);
        System.out.println("Total balance: " + (totalInterestEarned + totalInterestPaid));
    }
}
